      border: 1px solid rgba(239, 68, 68, 0.25);
      color: #f87171;
    }

    @media (max-width: 500px) {
      .form-container { padding: 1.5rem 1rem; }
      .form-row.half { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <div class="form-container">
    <div class="logo-section">
      <h1>MIFECO</h1>
      <div class="tagline">SaaS Pipeline Intake</div>
    </div>

    <div class="divider"></div>

    <form id="saasIntakeForm" method="POST" action="https://agentmail.to/api/send">
      <input type="hidden" name="to" value="carefulvehicle192@agentmail.to">
      <input type="hidden" name="subject" value="New SaaS Pipeline Lead">

      <div class="form-row">
        <label for="company_name">Company Name <span class="required">*</span></label>
        <input type="text" id="company_name" name="company_name" placeholder="e.g. TechFlow Labs" required>
      </div>

      <div class="form-row">
        <label for="website">Website</label>
        <input type="url" id="website" name="website" placeholder="https://example.com">
      </div>

      <div class="form-row half">
        <div>
          <label for="contact_name">Contact Name <span class="required">*</span></label>
          <input type="text" id="contact_name" name="contact_name" placeholder="Full name" required>
        </div>
        <div>
          <label for="contact_email">Contact Email <span class="required">*</span></label>
          <input type="email" id="contact_email" name="contact_email" placeholder="name@company.com" required>
        </div>
      </div>

      <div class="form-row half">
        <div>
          <label for="phone">Phone</label>
          <input type="tel" id="phone" name="phone" placeholder="+1 (555) 123-4567">
        </div>
        <div>
          <label for="employee_count">Employee Count</label>
          <select id="employee_count" name="employee_count">
            <option value="">— Select —</option>
            <option value="1-10">1–10</option>
            <option value="11-50">11–50</option>
            <option value="51-200">51–200</option>
            <option value="201-1000">201–1,000</option>
            <option value="1001+">1,001+</option>
          </select>
        </div>
      </div>

      <div class="form-row">
        <label for="product_interest">Product Interest <span class="required">*</span></label>
        <select id="product_interest" name="product_interest" required>
          <option value="">— Select a product —</option>
          <option value="Project Hypatia Pro">Project Hypatia Pro</option>
          <option value="PM Accelerator">PM Accelerator</option>
          <option value="VibraEngineer">VibraEngineer</option>
        </select>
      </div>

      <div class="form-row">
        <label for="pain_points">Pain Points</label>
        <textarea id="pain_points" name="pain_points" placeholder="Describe the key challenges or pain points your team is facing..."></textarea>
      </div>

      <div class="form-row">
        <label for="referral_source">Referral Source</label>
        <select id="referral_source" name="referral_source">
          <option value="">— How did you hear about us? —</option>
          <option value="LinkedIn">LinkedIn</option>
          <option value="Google">Google Search</option>
          <option value="Twitter/X">Twitter / X</option>
          <option value="Referral">Referral from a colleague</option>
          <option value="Conference">Conference / Event</option>
          <option value="Podcast">Podcast</option>
          <option value="Blog">Blog / Newsletter</option>
          <option value="Other">Other</option>
        </select>
      </div>

      <div class="divider"></div>

      <button type="submit" class="submit-btn" id="submitBtn">Submit Lead → Pipeline</button>

      <div id="statusMsg" class="status-msg"></div>

      <div class="form-footer">
        Powered by <a href="#">MIFECO Pipeline Engine</a>
      </div>
    </form>
  </div>

  <script>
    (function() {
      const form = document.getElementById('saasIntakeForm');
      const submitBtn = document.getElementById('submitBtn');
      const statusMsg = document.getElementById('statusMsg');

      form.addEventListener('submit', async function(e) {
        e.preventDefault();

        submitBtn.disabled = true;
        submitBtn.textContent = 'Submitting...';
        statusMsg.className = 'status-msg';
        statusMsg.style.display = 'none';

        const formData = new FormData(form);
        const payload = {};
        formData.forEach((value, key) => { payload[key] = value; });

        try {
          const response = await fetch('https://agentmail.to/api/send', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });

          if (!response.ok) {
            const errText = await response.text().catch(() => 'Unknown error');
            throw new Error('Server responded with ' + response.status + ': ' + errText);
          }

          statusMsg.className = 'status-msg success';
          statusMsg.textContent = '✓ Lead submitted successfully. We will follow up shortly.';
          statusMsg.style.display = 'block';
          form.reset();

        } catch (err) {
          console.error('Form submission error:', err);
          statusMsg.className = 'status-msg error';
          statusMsg.textContent = '✗ Submission failed: ' + err.message + '. Please try again.';
          statusMsg.style.display = 'block';
        } finally {
          submitBtn.disabled = false;
          submitBtn.textContent = 'Submit Lead → Pipeline';
        }
      });
    })();
  </script>
</body>
</html>
